import { db } from "../lib/db";
import { decryptSecret } from "../lib/crypto-box";

async function main() {
  const s = await db.server.findUnique({
    where: { id: "cmsc9l72y000ghl7iyd87u5ja" },
    select: { id: true, name: true, hostname: true, ipAddress: true, sshPort: true, rootPasswordEnc: true, status: true },
  });
  if (!s) { console.log("NO SERVER"); return; }
  if (s.ipAddress !== "51.79.226.200") {
    console.log("IP MISMATCH — refusing:", s.ipAddress);
    await db.$disconnect();
    process.exit(2);
  }
  const pw = decryptSecret(s.rootPasswordEnc);
  console.log(JSON.stringify({ id: s.id, name: s.name, hostname: s.hostname, ip: s.ipAddress, port: s.sshPort ?? 22, status: s.status, pw }, null, 2));
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });

import { Client } from "ssh2";
import { readFileSync } from "node:fs";
import { db } from "../lib/db";
import { decryptSecret } from "../lib/crypto-box";

// Runs a command (read from file given as argv[2]) on the Soul Pilates staging box.
// ASSERTS ip == 51.79.226.200 before connecting.
async function main() {
  const cmdFile = process.argv[2];
  const cmd = readFileSync(cmdFile, "utf8");
  const s = await db.server.findUnique({
    where: { id: "cmsc9l72y000ghl7iyd87u5ja" },
    select: { ipAddress: true, sshPort: true, rootPasswordEnc: true },
  });
  await db.$disconnect();
  if (!s) throw new Error("no server");
  if (s.ipAddress !== "51.79.226.200") throw new Error("IP MISMATCH: " + s.ipAddress);
  const password = decryptSecret(s.rootPasswordEnc);
  if (!password) throw new Error("no pw");
  const host = s.ipAddress;
  const port = s.sshPort ?? 22;

  const conn = new Client();
  await new Promise<void>((res, rej) => {
    conn.on("ready", () => res()).on("error", rej).connect({ host, port, username: "root", password, readyTimeout: 20000 });
  });
  const result = await new Promise<{ code: number | null; out: string; err: string }>((res, rej) => {
    conn.exec(cmd, (err, stream) => {
      if (err) return rej(err);
      let out = "", er = "";
      stream.on("close", (code: number | null) => res({ code, out, err: er }))
        .on("data", (d: Buffer) => (out += d.toString()))
        .stderr.on("data", (d: Buffer) => (er += d.toString()));
    });
  });
  conn.end();
  process.stdout.write(result.out);
  if (result.err) process.stderr.write("\n[STDERR]\n" + result.err);
  process.exit(result.code ?? 0);
}
main().catch((e) => { console.error(e); process.exit(1); });

