1	using Microsoft.Extensions.Configuration;
2	using Microsoft.Extensions.Logging;
3	using MongoDB.Driver;
4	using SoulPilates.Core.Entities;
5	using SoulPilates.Core.Interfaces;
6	using SoulPilates.Infrastructure.Data;
7	
8	namespace SoulPilates.Services;
9	
10	/// <summary>
11	/// Issue #5 — retention check-in reminders.
12	///
13	/// <para>
14	/// Twin of <see cref="ReminderService"/>, but the "due window" semantic is
15	/// inverted: instead of "session starts in N hours", it's "last check-in was
16	/// N days ago and the package still has credits". Each window label (e.g.
17	/// <c>"14d"</c>) is tracked on <see cref="ClientPackage.RetentionRemindersSent"/>
18	/// so re-running the job is safe — every package + window pair is emailed at
19	/// most once. Settings come from <see cref="GlobalSettings"/> so the studio
20	/// can tweak cadence + windows live without redeploys.
21	/// </para>
22	///
23	/// <para>
24	/// Send-then-tag ordering: the email goes out first, then the tag is
25	/// $push-appended. If the SMTP call throws, we leave the tag off so the next
26	/// tick retries.
27	/// </para>
28	/// </summary>
29	public class RetentionReminderService : IRetentionReminderService
30	{
31	    private readonly IMongoCollection<ClientPackage> _packages;
32	    private readonly IMongoCollection<Attendance> _attendances;
33	    private readonly IMongoCollection<Client> _clients;
34	    private readonly IEmailService _emailService;
35	    private readonly ISettingsService _settings;
36	    private readonly ILogger<RetentionReminderService> _logger;
37	    private readonly string _publicBaseUrl;
38	
39	    public RetentionReminderService(
40	        MongoDbContext db,
41	        IEmailService emailService,
42	        ISettingsService settings,
43	        ILogger<RetentionReminderService> logger,
44	        IConfiguration configuration)
45	    {
46	        _packages = db.GetCollection<ClientPackage>("ClientPackages");
47	        _attendances = db.GetCollection<Attendance>("Attendances");
48	        _clients = db.GetCollection<Client>("Clients");
49	        _emailService = emailService;
50	        _settings = settings;
51	        _logger = logger;
52	        var rawBase = configuration["PublicSite:BaseUrl"];
53	        _publicBaseUrl = string.IsNullOrWhiteSpace(rawBase) ? "http://localhost:4321" : rawBase.TrimEnd('/');
54	    }
55	
56	    public async Task<int> SendDueRemindersAsync(DateTime nowUtc, CancellationToken ct = default)
57	    {
58	        var s = await _settings.GetAsync(ct);
59	        if (!s.EnableRetentionReminders) return 0;
60	
61	        var windows = (s.RetentionReminderWindows ?? new())
62	            .Select(w => (Tag: w, Days: ParseDays(w)))
63	            .Where(p => p.Days > 0)
64	            .OrderByDescending(p => p.Days) // Send the largest-gap reminder first so older inactivity gets the firmer copy.
65	            .ToList();
66	
67	        if (windows.Count == 0) return 0;
68	
69	        var sent = 0;
70	        foreach (var (tag, days) in windows)
71	        {
72	            // A package is eligible for window `tag` when:
73	            //   - It is currently active (status ACTIVE/LOW_BALANCE — not expired/completed).
74	            //   - CreditsRemaining ≥ configured floor — exhausted packs belong on a re-buy nudge, not a retention nudge.
75	            //   - Its last CHECKED_IN attendance is older than `days` (or there's no check-in ever).
76	            //   - This `tag` is not already on RetentionRemindersSent.
77	            var filter = Builders<ClientPackage>.Filter.And(
78	                Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),
79	                Builders<ClientPackage>.Filter.Gte(p => p.CreditsRemaining, s.RetentionReminderMinCreditsRemaining),
80	                Builders<ClientPackage>.Filter.Not(Builders<ClientPackage>.Filter.AnyEq(p => p.RetentionRemindersSent, tag))
81	            );
82	
83	            // Fetch in batches to avoid loading the full catalogue at once. A studio with
84	            // ~5k active packages stays comfortable in this range; tune via PageSize if
85	            // we ever get an order of magnitude bigger.
86	            var cursor = await _packages.Find(filter).ToCursorAsync(ct);
87	            while (await cursor.MoveNextAsync(ct))
88	            {
89	                foreach (var pkg in cursor.Current)
90	                {
91	                    if (ct.IsCancellationRequested) return sent;
92	
93	                    // Most-recent CHECKED_IN attendance for this client. We sort by BookedAt;
94	                    // the booking flow stamps BookedAt at booking time and we have no separate
95	                    // "checked-in at" column, so this is the best proxy. If a client has never
96	                    // checked in we treat ActivationDate as their effective start.
97	                    var lastCheckIn = await _attendances
98	                        .Find(a => a.ClientId == pkg.ClientId && a.Status == "CHECKED_IN")
99	                        .SortByDescending(a => a.BookedAt)
100	                        .Limit(1)
101	                        .FirstOrDefaultAsync(ct);
102	
103	                    var anchor = lastCheckIn?.BookedAt ?? pkg.ActivationDate;
104	                    var inactiveDays = (nowUtc - anchor).TotalDays;
105	                    if (inactiveDays < days) continue;
106	
107	                    var client = await _clients.Find(c => c.Id == pkg.ClientId)
108	                        .FirstOrDefaultAsync(ct);
109	                    if (client is null || string.IsNullOrWhiteSpace(client.Email) || client.RetentionRemindersOptedOut)
110	                    {
111	                        // No email, or opted-out = silently tag so we don't re-query forever, skip the send.
112	                        await TagSentAsync(pkg.Id, tag, ct);
113	                        continue;
114	                    }
115	
116	                    try
117	                    {
118	                        // Ensure a stable, unguessable token for the one-click unsubscribe link.
119	                        var unsubToken = client.UnsubscribeToken;
120	                        if (string.IsNullOrWhiteSpace(unsubToken))
121	                        {
122	                            unsubToken = Guid.NewGuid().ToString("N");
123	                            await _clients.UpdateOneAsync(
124	                                c => c.Id == client.Id,
125	                                Builders<Client>.Update.Set(c => c.UnsubscribeToken, unsubToken),
126	                                cancellationToken: ct);
127	                        }
128	                        var unsubUrl = $"{_publicBaseUrl}/api/retention/unsubscribe?token={unsubToken}";
129	
130	                        var subject = $"We miss you at Soul Pilates";
131	                        var heading = $"Hi {FirstName(client.FullName)}, your mat is waiting";
132	                        var expiryLine = pkg.ExpiryDate.HasValue
133	                            ? $" (expires {pkg.ExpiryDate.Value:MMM d})"
134	                            : string.Empty;
135	                        var body =
136	                            $"It's been about {Math.Floor(inactiveDays):0} days since your last class and your package " +
137	                            $"still has {pkg.CreditsRemaining} credit{(pkg.CreditsRemaining == 1 ? "" : "s")}" +
138	                            $"{expiryLine}. Pick a class that fits your week — we'd love to see you on the reformer." +
139	                            $"\n\nPrefer not to receive these check-in reminders? Unsubscribe: {unsubUrl}";
140	                        await _emailService.SendGenericAsync(
